199	{
200	    ATB_LOG(DEBUG) << "ContextBase aclrtCreateStream start";
201	    aclError ret = aclrtCreateStream(&asyncTilingCopyStream_);
202	    if (ret != ACL_SUCCESS) {
203	        ATB_LOG(ERROR) << "ContextBase aclrtCreateStream fail, ret:" << ret;
204	        return ERROR_CANN_ERROR;
205	    }
206	    ATB_LOG(INFO) << "ContextBase aclrtCreateStream create success";
207	
208	    ATB_LOG(INFO) << "ContextBase try create event:" << MAX_COPY_EVENT_NUM;
209	    asyncTilingCopyEvents_.resize(MAX_COPY_EVENT_NUM);
210	    for (size_t i = 0; i < asyncTilingCopyEvents_.size(); i++) {
211	        asyncTilingCopyEvents_.at(i) = nullptr;
212	        ret = aclrtCreateEvent(&asyncTilingCopyEvents_.at(i));
213	        if (ret != ACL_SUCCESS) {
214	            ATB_LOG(ERROR) << "ContextBase aclrtCreateEvent ret:" << ret;
215	            return ERROR_CANN_ERROR;
216	        }
217	        ATB_LOG(INFO) << "ContextBase aclrtCreateEvent create success";
218	    }
219	
220	    return NO_ERROR;
