223	Status ContextBase::DestoryCopyStreamAndEvents()
224	{
225	    aclError ret = ACL_SUCCESS;
226	    if (asyncTilingCopyStream_) {
227	        ret = aclrtSynchronizeStream(asyncTilingCopyStream_);
228	        ATB_LOG_IF(ret != ACL_SUCCESS, ERROR) << "aclrtSynchronizeStream fail, ret:" << ret;
229	        ret = aclrtDestroyStream(asyncTilingCopyStream_);
230	        ATB_LOG_IF(ret != ACL_SUCCESS, ERROR) << "aclrtDestroyStream fail, ret:" << ret;
231	    }
232	    for (size_t i = 0; i < asyncTilingCopyEvents_.size(); i++) {
233	        if (asyncTilingCopyEvents_.at(i)) {
234	            ret = aclrtSynchronizeEvent(asyncTilingCopyEvents_.at(i));
235	            ATB_LOG_IF(ret != ACL_SUCCESS, ERROR) << "aclrtSynchronizeEvent fail, ret:" << ret;
236	            ret = aclrtDestroyEvent(asyncTilingCopyEvents_.at(i));
237	            ATB_LOG_IF(ret != ACL_SUCCESS, ERROR) << "aclrtDestroyEvent fail, ret:" << ret;
238	            asyncTilingCopyEvents_.at(i) = nullptr;
239	        }
240	    }
241	
242	    return NO_ERROR;
243	}
