228	int main()
229	{
230	    aclInit(nullptr);
231		// 设置卡号、创建stream、创建context、设置stream
232	    uint32_t deviceId = 1;
233	    aclrtSetDevice(deviceId);
234	    // 创建多个stream
235	    aclrtStream stream1 = nullptr;
236	    aclrtCreateStream(&stream1);
237	    aclrtStream stream2 = nullptr;
238	    aclrtCreateStream(&stream2);
239	    std::vector<aclrtStream> streams = {stream1, stream2};
240	
241	    atb::Context *context = nullptr;
242	    atb::CreateContext(&context);
243	    context->SetExecuteStreams(streams);
244	    // 创建图内多流并行Op
245	    atb::Operation *operation = nullptr;
246	    atb::GraphParam opGraph;
247	    CreateGraphOperationForMultiStream(opGraph, &operation);
248	
249		// 输入输出tensor准备
250	    atb::VariantPack pack;
251	    atb::SVector<atb::TensorDesc> intensorDescs;
252	    atb::SVector<atb::TensorDesc> outtensorDescs;
253	
254	    uint32_t inTensorNum = opGraph.inTensorNum;
255	    uint32_t outTensorNum = opGraph.outTensorNum;
256	    inTensorNum = operation->GetInputNum();
257	    outTensorNum = operation->GetOutputNum();
258	
259	    pack.inTensors.resize(inTensorNum);
260	    intensorDescs.resize(inTensorNum);
261	    
262	    CreateInTensorDescs(intensorDescs);
263	    
264	    outtensorDescs.resize(outTensorNum);
265	    pack.outTensors.resize(outTensorNum);
266	    operation->InferShape(intensorDescs, outtensorDescs);
267	    aclError ret = CreateOutTensors(pack.outTensors, outtensorDescs);
268	    if (ret != 0) {
269	        exit(ret);
270	    }
271	
272	    // 初始化workspace
273	    uint64_t workspaceSize = 0;
274	    void *workSpace = nullptr;
275	    // 图内多流并行
276	    std::cout << "Single graph multi-stream demo start" << std::endl;
277	    ret = CreateInTensors(pack.inTensors, intensorDescs);
278	    if (ret != 0) {
279	        exit(ret);
280	    }
281	    operation->Setup(pack, workspaceSize, context);
282	    if (workspaceSize != 0 && workSpace == nullptr) {
283	        ret = aclrtMalloc(&workSpace, workspaceSize, ACL_MEM_MALLOC_HUGE_FIRST);
284	        if (ret != 0) {
285	            std::cout << "alloc error!\n";
286	            exit(1);
287	        }
288	    }
289	    operation->Execute(pack, (uint8_t*)workSpace, workspaceSize, context);
290	    // 流同步
291	    ret = aclrtSynchronizeStream(stream1);
292	    if (ret != 0) {
293	        std::cout << "sync error!";
294	        exit(1);
295	    }
296	
297	    ret = aclrtSynchronizeStream(stream2);
298	    if (ret != 0) {
299	        std::cout << "sync error!";
300	        exit(1);
301	    }
302	
303		// 资源释放
304	    atb::DestroyOperation(operation);
305	    atb::DestroyContext(context);
306	    for (size_t i = 0; i < pack.inTensors.size(); i++) {
307	        aclrtFree(pack.inTensors.at(i).deviceData);
308	    }
309	    for (size_t i = 0; i < pack.outTensors.size(); i++) {
310	        aclrtFree(pack.outTensors.at(i).deviceData);
311	    }
312	    aclrtFree(workSpace);
313	    aclrtDestroyStream(stream1);
314	    aclrtDestroyStream(stream2);
315	    aclrtResetDevice(deviceId);
316	    aclFinalize();
317	}
